import{z as s,x as A,o as E,c as l,q as o,j as r,D as a,d as i,s as n,S as d}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"格式化字符串","description":"","frontmatter":{"title":"格式化字符串","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/format-string.md","filePath":"cs/format-string.md","lastUpdated":1791063341000}'),B={name:"cs/format-string.md"};function c(p,e,f,D,_,h){const t=A("Mermaid");return E(),l("div",null,[e[2]||(e[2]=o('<h1 id="格式化字符串" tabindex="-1">格式化字符串 <a class="header-anchor" href="#格式化字符串" aria-label="Permalink to &quot;格式化字符串&quot;">​</a></h1><div class="epigraph"><p>`printf` 的格式串是微型语言。若把用户输入当成格式，说明符会去读（历史上甚至写）栈上的参数槽。正确合同：格式串是程序员常量。</p><footer>—— 据 CWE-134；对照 Newsham 与其他早期公开分析；ISO C `fprintf` 合同</footer></div><p>上一课<a href="/cs/integer-overflow-bugs">整数溢出</a>的洞出在算术上，本课的洞出在<strong>解释</strong>上：同一段字节被当成微型语言执行。合同一句话：格式串必须是程序员写死的常量，不可信数据只能作实参进去。本课钉下这份合同，不给 <code>%n</code> 的利用步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>典型现场是日志：<code>printf(user)</code>。C 的变参机制不携带参数个数与类型信息，<code>printf</code> 全靠扫格式串自数：每遇一个说明符就取下一个参数。参数不够时它不报错，继续向栈上取——取到的是调用现场残留的任何字节，解释全由攻击者的串指挥：<code>%x</code> 把残留当十六进制吐进日志，<code>%s</code> 更把残留值当指针去解引用；历史上 <code>%n</code> 还能把已输出字节数写进指定地址，把一次日志调用变成写内存的原语。修法在 API 层：<code>printf(&quot;%s&quot;, user)</code>，让用户串只当数据。编译器 <code>-Wformat-security</code> 能抓「格式位不是字面量」的一部分，抓不完。</p><h3 id="n-已在许多-libc-弱化" tabindex="-1">%n 已在许多 libc 弱化 <a class="header-anchor" href="#n-已在许多-libc-弱化" aria-label="Permalink to &quot;%n 已在许多 libc 弱化&quot;">​</a></h3><p>许多 libc 已把 <code>%n</code> 弱化（只读段、FORTIFY 检查），但只要格式串可控，读栈的泄漏就还在。合同不因缓解而放松：格式常量。</p><p><span class="marginnote">术语翻译「变参机制」：C 的可变参数函数不携带「一共几个参数、各是什么类型」的清单，printf 只能靠扫格式串自数。可以想象成点菜：订单上写着 5 道菜，厨房就端 5 道；订单若是攻击者写的「100 道」，厨房不够菜就把后厨现有的存货（栈上残留）也端了出去。</span></p><p><span class="marginnote">CWE-134。本课禁止构造恶意格式串作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是对着写：同一行日志，不安全调用把用户串放格式位，安全调用把它降为 <code>%s</code> 实参；判断标准只有一条——格式位上是谁写的字符串。日志库应当自带格式、调用者只传参数，把「格式常量」做进接口，让错误调用写不出来。类型混淆下一课把「解释错误」升到对象层。</p>',12)),(E(),r(d,null,{default:a(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E4%B8%B2%22%5D%20--%3E%20BAD%5B%22%E5%BD%93%E4%BD%9C%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20BAD%20--%3E%20LEAK%5B%22%E8%AF%BB%E9%94%99%E5%8F%82%E6%95%B0%E6%A7%BD%22%5D%0A%20%20CST%5B%22%E5%B8%B8%E9%87%8F%E6%A0%BC%E5%BC%8F%22%5D%20--%3E%20OK%5B%22%E7%94%A8%E6%88%B7%E5%8F%AA%E5%BD%93%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>深一层的读法：这份合同把「数据」与「解释规则」分开——输入只能是数据，解释规则必须由程序固定。<code>printf(user)</code> 的错误正是让输入选择解释规则，顺带选择了去读哪些内存；这不是越界，是授了解释权。下一课类型混淆是同一原理的对象层版本：选错虚表或 union 分支，同样是解释规则与对象不匹配。</p><p><span class="marginnote">初学者容易以为「printf 多读了顶多显示乱码，无伤大雅」。实际上 <code>%x</code> 每消费一个参数槽就吐出 4-8 字节的栈残留，连写一排 <code>%x</code> 就能把函数指针、密钥片段倒进日志；<code>%s</code> 更是把残留值直接当地址去解引用。读是泄漏，历史上 <code>%n</code> 甚至能写。</span></p>',3)),(E(),r(d,null,{default:a(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%A0%BC%E5%BC%8F%E4%B8%B2%E6%98%AF%E8%B0%81%E5%86%99%E7%9A%84%3F%22%5D%20--%3E%20SCAN%5B%22printf%20%E6%89%AB%E6%A0%BC%E5%BC%8F%E4%B8%B2%2C%E6%AF%8F%E9%81%87%E4%B8%80%E4%B8%AA%E8%AF%B4%E6%98%8E%E7%AC%A6%E5%8F%96%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%8F%82%E6%95%B0%E6%A7%BD%22%5D%0A%20%20SCAN%20--%3E%20E1%5B%22%25x%3A%20%E6%8A%8A%E6%A7%BD%E6%8C%89%E5%8D%81%E5%85%AD%E8%BF%9B%E5%88%B6%E6%89%93%E5%8D%B0%22%5D%0A%20%20SCAN%20--%3E%20E2%5B%22%25s%3A%20%E6%8A%8A%E6%A7%BD%E5%BD%93%E6%8C%87%E9%92%88%2C%E8%A7%A3%E5%BC%95%E7%94%A8%E6%89%93%E5%8D%B0%22%5D%0A%20%20E1%20--%3E%20DEP%5B%22%E5%AE%9E%E5%8F%82%E7%94%A8%E5%AE%8C%E4%BA%86%22%5D%0A%20%20E2%20--%3E%20DEP%0A%20%20DEP%20--%3E%20RES%5B%22%E7%BB%A7%E7%BB%AD%E5%8F%96%E6%A0%88%E4%B8%8A%E6%AE%8B%E7%95%99%E5%AD%97%E8%8A%82%E5%BD%93%E5%8F%82%E6%95%B0%22%5D%0A%20%20RES%20--%3E%20LEAK%5B%22%E5%86%85%E5%AD%98%E5%86%85%E5%AE%B9%E8%A2%AB%E5%80%92%E8%BF%9B%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给泄漏或写入的配方，说明符语义以 ISO C 的 <code>fprintf</code> 合同为准；类型混淆在下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长度算错之外，格式串是微型语言。</li><li>不可信数据不得当格式。</li><li>编译器警告是辅助，不是证明。</li><li>下一课类型混淆。</li><li>出处：CWE-134；ISO C；对照 Szekeres SoK。</li></ul>',4))])}const u=s(B,[["render",c]]);export{C as __pageData,u as default};
